#!/bin/bash
set -eo pipefail
umask 077
test "$(id -un)" = sunyiq
for parent in / /data1 /data1/home /data1/home/sunyiq; do
  test -d "$parent"
  test ! -L "$parent"
  test "$(readlink -e "$parent")" = "$parent"
done
test ! -e '/data1/home/sunyiq/us_nonnegative_input_probe_20261007_001'
test ! -L '/data1/home/sunyiq/us_nonnegative_input_probe_20261007_001'
mkdir '/data1/home/sunyiq/us_nonnegative_input_probe_20261007_001'
mkdir '/data1/home/sunyiq/us_nonnegative_input_probe_20261007_001/src' '/data1/home/sunyiq/us_nonnegative_input_probe_20261007_001/contracts' '/data1/home/sunyiq/us_nonnegative_input_probe_20261007_001/logs'
set -o noclobber
printf '%s' '' | base64 -d > '/data1/home/sunyiq/us_nonnegative_input_probe_20261007_001/src/probe_us_input_headers_v1.py'
printf '%s  %s\n' '504b39f6485200b39dccc0f968b410a5f41936ac5081ac551c460d13a92cc835' '/data1/home/sunyiq/us_nonnegative_input_probe_20261007_001/src/probe_us_input_headers_v1.py' | sha256sum -c -
printf '%s' '' | base64 -d > '/data1/home/sunyiq/us_nonnegative_input_probe_20261007_001/contracts/INPUT_HEADER_SCOPE_v1.json'
printf '%s  %s\n' 'ae14c982b0490f3209e36c8d33b387264fccb7c4d7ceeb8990d9e7ad42971472' '/data1/home/sunyiq/us_nonnegative_input_probe_20261007_001/contracts/INPUT_HEADER_SCOPE_v1.json' | sha256sum -c -
printf '%s' '' | base64 -d > '/data1/home/sunyiq/us_nonnegative_input_probe_20261007_001/input_headers_v1.sbatch'
printf '%s  %s\n' '4441814541dcb74cfd70e334c2ceec003dab3f53d7f22756564bd3f7ff416984' '/data1/home/sunyiq/us_nonnegative_input_probe_20261007_001/input_headers_v1.sbatch' | sha256sum -c -
job=$(sbatch --parsable '/data1/home/sunyiq/us_nonnegative_input_probe_20261007_001/input_headers_v1.sbatch')
case "$job" in ''|*[!0-9]*) exit 1;; esac
printf '%s\n' "$job" > '/data1/home/sunyiq/us_nonnegative_input_probe_20261007_001/job_id.txt'
printf 'INPUT_HEADER_ROOT=/data1/home/sunyiq/us_nonnegative_input_probe_20261007_001\nINPUT_HEADER_JOB_ID=%s\nINPUT_HEADER_SUBMITTED_ONCE\n' "$job"
